const [addTodo] = useMutation(ADD_TODO, {
  optimisticResponse: {
    addTodo: {
      id: 'temp-' + Date.now(),
      title: newTodo.title,
      completed: false,
      __typename: 'Todo',
    },
  },
  update: (cache, { data }) => {
    cache.modify({
      fields: {
        todos: (existing = []) => [...existing, data?.addTodo],
      },
    });
  },
});
